// Package db owns the Postgres connection pool and schema migrations.
// Query code is generated by sqlc into this package — do not name files
// db.go, models.go, querier.go, or <name>.sql.go here, sqlc overwrites them.
package db

import (
	"context"
	"database/sql"
	"fmt"
	"io/fs"

	schemadb "github.com/Dvorinka/tock/db"
	"github.com/jackc/pgx/v5/pgxpool"
	_ "github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
)

// baselineVersion is the goose version of db/migrations/00001_baseline.sql.
// A restored upstream dump has all tables but no goose_db_version row; it is
// marked as baseline-applied instead of re-running the DDL.
const baselineVersion int64 = 1

// Open returns a pgx connection pool for the given DSN.
func Open(ctx context.Context, dsn string) (*pgxpool.Pool, error) {
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return nil, fmt.Errorf("parse dsn: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("ping database: %w", err)
	}
	return pool, nil
}

// Migrate applies pending migrations. If the database already contains the
// upstream schema (restored solidtime dump) but no goose version table, the
// baseline is marked applied without executing it.
func Migrate(ctx context.Context, dsn string) error {
	sqlDB, err := sql.Open("pgx", dsn)
	if err != nil {
		return fmt.Errorf("open database: %w", err)
	}
	defer func() { _ = sqlDB.Close() }()

	if err := markBaselineIfRestored(ctx, sqlDB); err != nil {
		return err
	}

	migrations, err := fs.Sub(schemadb.Migrations, "migrations")
	if err != nil {
		return fmt.Errorf("migrations fs: %w", err)
	}
	provider, err := goose.NewProvider(goose.DialectPostgres, sqlDB, migrations)
	if err != nil {
		return fmt.Errorf("goose provider: %w", err)
	}
	if _, err := provider.Up(ctx); err != nil {
		return fmt.Errorf("apply migrations: %w", err)
	}
	return nil
}

// markBaselineIfRestored detects a database restored from an upstream dump
// (the users table exists) with no recorded schema version, and records the
// baseline migration as applied. The goose_db_version DDL matches goose's
// postgres dialect exactly.
func markBaselineIfRestored(ctx context.Context, sqlDB *sql.DB) error {
	var usersExists bool
	if err := sqlDB.QueryRowContext(ctx, `
		SELECT EXISTS (
			SELECT 1 FROM pg_tables
			WHERE schemaname = 'public' AND tablename = 'users'
		)`).Scan(&usersExists); err != nil {
		return fmt.Errorf("check existing schema: %w", err)
	}
	if !usersExists {
		return nil
	}

	var versionExists bool
	if err := sqlDB.QueryRowContext(ctx, `
		SELECT EXISTS (
			SELECT 1 FROM pg_tables
			WHERE schemaname = 'public' AND tablename = 'goose_db_version'
		)`).Scan(&versionExists); err != nil {
		return fmt.Errorf("check version table: %w", err)
	}

	var maxVersion int64
	if versionExists {
		if err := sqlDB.QueryRowContext(ctx,
			`SELECT COALESCE(max(version_id), 0) FROM goose_db_version`).Scan(&maxVersion); err != nil {
			return fmt.Errorf("get db version: %w", err)
		}
	}
	if maxVersion != 0 {
		return nil
	}

	if !versionExists {
		if _, err := sqlDB.ExecContext(ctx, `
			CREATE TABLE goose_db_version (
				id integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
				version_id bigint NOT NULL,
				is_applied boolean NOT NULL,
				tstamp timestamp NOT NULL DEFAULT now()
			)`); err != nil {
			return fmt.Errorf("create version table: %w", err)
		}
	}
	if _, err := sqlDB.ExecContext(ctx,
		`INSERT INTO goose_db_version (version_id, is_applied) VALUES ($1, true)`,
		baselineVersion); err != nil {
		return fmt.Errorf("mark baseline applied: %w", err)
	}
	return nil
}
